 function tick(){if(!state.alive||!pending(order))return;if(expired()){void showOrder();return;}const target=q('[data-payment-expiry]');if(target&&order.expiresAt){const seconds=Math.max(0,Math.ceil((Date.parse(order.expiresAt)-Date.now())/1000));target.textContent=Number.isFinite(seconds)?`付款剩余 ${Math.floor(seconds/60)} 分 ${String(seconds%60).padStart(2,'0')} 秒`:'';}tickTimer=state.later(tick,1000);}
