/** Orders are always fetched from the authenticated account; no local demo records. */
export async function renderPaymentOrders({container=document.querySelector('.dashboard'),navigate}={}){
 const state=lifecycle(container),q=selector=>container.querySelector(selector);let loading=false;
 const go=href=>navigate?navigate(href):location.hash=href;
 async function load(){if(loading||!state.alive)return;loading=true;const refresh=q('[data-orders-refresh]');if(refresh)refresh.disabled=true;try{const account=await state.api('/auth/me');if(!account.user){container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+login();return;}const data=await state.api('/orders');const items=Array.isArray(data.items)?data.items:[];container.innerHTML=heading('我的订单','订单状态与金额来自服务器记录。请勿对同一笔订单重复付款。',true)+`<section class="payment-card payment-history"><header><div><h2>账户订单 <span>${items.length}</span></h2><p>购买记录与付款状态统一查看。</p></div><button type="button" class="btn secondary" data-orders-refresh>${icon('clock',15)}刷新订单</button></header>${items.length?`<div class="payment-order-list">${items.map(item=>`<article class="payment-history-item"><div class="payment-history-main"><span class="payment-provider-mark ${item.provider==='wechat'?'wechat':'alipay'}" aria-hidden="true">${item.provider==='wechat'?'微':'支'}</span><div><h3>${esc(item.title)}</h3><p>${purchaseType(item)} · ${channelName(item.provider)} · ${date(item.createdAt)}</p><small>订单号 ${esc(item.outTradeNo||item.id)}</small></div></div><div class="payment-history-state"><strong>${money(item.amountCents)}</strong><span class="payment-status ${item.status==='paid'?'is-paid':pending(item)?'is-pending':'is-closed'}">${statusLabels[item.status]||'状态待确认'}</span></div><button type="button" class="btn secondary" data-payment-order="${esc(item.id)}">${pending(item)?'继续支付':'查看订单'}</button></article>`).join('')}</div>`:`<div class="payment-empty">${icon('file',32)}<h3>还没有订单</h3><p>这里会展示你的真实购买记录。</p><a class="btn secondary" href="${checkoutHref()}">查看可购服务</a></div>`}<p class="payment-history-note">如对订单有疑问，请联系 <a href="mailto:contact@oneshowailab.com">contact@oneshowailab.com</a> 并提供订单号，请勿发送支付密码。</p></section>`;q('[data-orders-refresh]').onclick=load;container.querySelectorAll('[data-payment-order]').forEach(button=>button.onclick=()=>go(checkoutHref({orderId:button.dataset.paymentOrder})));}catch(error){if(!state.alive||error.name==='AbortError')return;container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+(error.status===401?login():retry(error.message));q('[data-payment-retry]')?.addEventListener('click',load);}finally{loading=false;const button=q('[data-orders-refresh]');if(button)button.disabled=false;}}
 container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+'<section class="payment-card payment-empty" role="status">正在读取订单…</section>';
 await load();return state.cleanup;
}

export function disposePayment(container=document.querySelector('.dashboard')){if(container)mounts.get(container)?.();}
